(window.PSAC_DEMO_DECKS = window.PSAC_DEMO_DECKS || {})[1] = {"grade":1,"packs":{"grade1-english":{"g1eng-listening":[{"id":"g1eng-lis-008","q":"What sound does the letter T make?","opts":["/d/ like in door","/s/ like in sit","/t/ like in table","/k/ like in kite"],"a":"/t/ like in table","hint":"Think of the word \"table\". What sound does it start with? 🍽️","exp":"Well done! The letter T makes the /t/ sound, like in <b>table</b>, <b>top</b> and <b>toy</b>."},{"id":"g1eng-lis-062","q":"\"The flower is pink and pretty.\" What colour is the flower?","opts":["Pink","Red","Yellow","Blue"],"a":"Pink","hint":"Find the colour word in the sentence. 🌸","exp":"Well done! The sentence says the flower is <b>pink</b> and pretty."},{"id":"g1eng-lis-002","q":"Which animal says \"woof\"?","opts":["Cat","Duck","Dog","Frog"],"a":"Dog","hint":"This friendly animal is often a pet at home. 🐶","exp":"Well done! A <b>dog</b> says \"woof\". It is a popular pet and a very loyal friend."},{"id":"g1eng-lis-055","q":"\"Ana eats an apple every day.\" What does Ana eat?","opts":["A mango","An orange","A banana","An apple"],"a":"An apple","hint":"Find the food word in the sentence. 🍎","exp":"Well done! The sentence says Ana eats <b>an apple</b> every day."},{"id":"g1eng-lis-010","q":"Which animal makes a \"baa\" sound?","opts":["Lion","Dog","Cow","Sheep"],"a":"Sheep","hint":"This fluffy animal gives us wool. 🐑","exp":"Well done! A <b>sheep</b> makes the \"baa\" sound. Sheep have fluffy wool that keeps them warm."}],"g1eng-speaking":[{"id":"g1eng-spk-069","q":"Which is a complete sentence about food?","opts":["I love to eat mangoes.","mango eat love to I","mangoes love to eat","eat I mangoes to love"],"a":"I love to eat mangoes.","hint":"Find the sentence with a subject (I) and a verb (love). 🥭","exp":"Well done! <b>I love to eat mangoes</b> is a complete sentence."},{"id":"g1eng-spk-028","q":"What do we call the round thing you play football with?","opts":["Rope","Kite","Bat","Ball"],"a":"Ball","hint":"You kick it with your foot in football! ⚽","exp":"Well done! A <b>ball</b> is round and used in many sports like football."},{"id":"g1eng-spk-033","q":"What do we call the thing you carry your books in to school?","opts":["School bag","Box","Bucket","Basket"],"a":"School bag","hint":"You carry this on your back every school day. 🎒","exp":"Well done! A <b>school bag</b> is what we use to carry our books and lunch to school."},{"id":"g1eng-spk-005","q":"You want to ask a teacher a question. What do you say first?","opts":["Thank you!","Good night!","Goodbye!","Excuse me!"],"a":"Excuse me!","hint":"You say this when you want to get someone's attention politely. ✋","exp":"Well done! We say <b>Excuse me!</b> when we want to get someone's attention politely."},{"id":"g1eng-spk-031","q":"What do we call the big yellow thing that lights up the sky in the day?","opts":["Cloud","Sun","Moon","Star"],"a":"Sun","hint":"It gives us light and warmth during the day. ☀️","exp":"Well done! The <b>sun</b> is a big, bright star that gives us light and heat every day."}],"g1eng-reading":[{"id":"g1eng-rdr-051","q":"Which word do you use when you talk about yourself?","opts":["She","He","I","You"],"a":"I","hint":"When you talk about yourself, you use this little word. 😊","exp":"Well done! The word <b>I</b> is used when you talk about yourself."},{"id":"g1eng-rdr-001","q":"In which direction do we read English?","opts":["Left to right","Top to bottom only","Bottom to top","Right to left"],"a":"Left to right","hint":"Think about where your eyes start on a line of writing. 👀","exp":"Well done! We always read English from <b>left to right</b>, just like we write it."},{"id":"g1eng-rdr-029","q":"What is the capital letter of \"a\"?","opts":["B","D","A","C"],"a":"A","hint":"Every small letter has a big version called a capital. 🔠","exp":"Well done! The capital letter of \"a\" is <b>A</b>."},{"id":"g1eng-rdr-006","q":"How many words are in the sentence \"The cat sat.\"?","opts":["Three","One","Two","Four"],"a":"Three","hint":"Count the words: The — cat — sat. How many? 🐱","exp":"Well done! \"The cat sat.\" has <b>three</b> words: The, cat, sat."},{"id":"g1eng-rdr-071","q":"Which word means \"almost the same as\"?","opts":["But","And","Or","Like"],"a":"Like","hint":"Think of \"My bag is like yours\" — the two bags are almost the same.","exp":"Well done! <b>Like</b> means almost the same as. For example: \"My hat is <b>like</b> yours.\" It can also mean to enjoy something: \"I <b>like</b> cats.\""}]},"grade1-french":{"g1fr-comprehension-orale":[{"id":"g1fr-co-031","q":"Quel fruit est jaune et long ?","opts":["la mangue","la fraise","la banane","l'orange"],"a":"la banane","hint":"Ce fruit est courbé et jaune. (This fruit is curved and yellow.)","exp":"<b>La banane</b> est jaune et longue. Les singes adorent les bananes ! Super !"},{"id":"g1fr-co-019","q":"Le professeur dit : <i>\"Ouvrez votre livre à la page 5 !\"</i> Que font les élèves ?","opts":["ils posent leur livre","ils ferment leur livre","ils perdent leur livre","ils ouvrent leur livre"],"a":"ils ouvrent leur livre","hint":"\"Ouvrez\" = open! C'est une instruction. (It is an instruction to open.)","exp":"<b>\"Ouvrez votre livre\"</b> veut dire d'ouvrir le livre. Les élèves obéissent. Très bien !"},{"id":"g1fr-co-012","q":"Quel mot contient le son <b>/ou/</b> ?","opts":["sel","chat","ours","riz"],"a":"ours","hint":"Le son /ou/ est dans \"mouton\" et \"boule\". (The /ou/ sound is like \"oo\" in \"cool\".)","exp":"<b>Ours</b> contient le son /ou/. C'est un grand animal ! Super !"},{"id":"g1fr-co-059","q":"Quelle saison est chaude et ensoleillée à Maurice ?","opts":["l'hiver","le printemps","l'automne","l'été"],"a":"l'été","hint":"En quelle saison fait-il très chaud et le soleil brille beaucoup ?","exp":"<b>L'été</b> est la saison la plus chaude et ensoleillée. À Maurice, c'est entre novembre et avril."},{"id":"g1fr-co-066","q":"Écoute bien la <b>fin</b> des mots. Quel mot rime avec <b>chat</b> ?","opts":["roue","rue","riz","rat"],"a":"rat","hint":"Deux mots riment quand leur fin sonne pareil. (Rhyming words end with the same sound.)","exp":"« Chat » et « <b>rat</b> » finissent tous les deux par le son <b>/a/</b>. « Riz » finit par /i/, « rue » par /u/. (Chat rhymes with rat.)"}],"g1fr-expression-orale":[{"id":"g1fr-eo-001","q":"Quel mot rime avec <b>\"chat\"</b> ?","opts":["bus","fleur","sel","rat"],"a":"rat","hint":"Cherche un mot avec le même son à la fin : \"-a\". (Find a word with the same ending sound.)","exp":"<b>Rat</b> rime avec <b>chat</b> — les deux finissent par le son \"-a\". Bravo !"},{"id":"g1fr-eo-022","q":"Un ami demande : <i>\"Ça va ?\"</i> Tu réponds ...","opts":["Bonne nuit, dors bien !","Au revoir, à demain !","Bonjour, ça va ?","Ça va bien, merci !"],"a":"Ça va bien, merci !","hint":"\"Ça va ?\" = How are you? \"Ça va bien\" = I am fine. (This is a common greeting.)","exp":"Quand quelqu'un dit <b>\"Ça va ?\"</b>, on répond <b>\"Ça va bien, merci !\"</b> ou simplement \"Ça va\". C'est une salutation courante en français ! Bravo !"},{"id":"g1fr-eo-026","q":"Tu ne comprends pas ce que dit la maîtresse. Tu dis ...","opts":["Pardon, pouvez-vous répéter ?","Merci beaucoup, c'est gentil !","Bonsoir, je rentre chez moi !","Au revoir, à demain matin !"],"a":"Pardon, pouvez-vous répéter ?","hint":"On demande de répéter quand on n'a pas compris. (We ask to repeat when we did not understand.)","exp":"Quand on ne comprend pas, on dit <b>\"Pardon, pouvez-vous répéter ?\"</b> — Excuse me, could you repeat please? C'est toujours bon de demander ! Bravo !"},{"id":"g1fr-eo-050","q":"Comment demandes-tu à un ami comment il va ?","opts":["Quel âge as-tu ?","Qu'est-ce que tu manges ?","Comment vas-tu ?","Où habites-tu ?"],"a":"Comment vas-tu ?","hint":"Pour savoir si ton ami va bien, quelle question poses-tu ?","exp":"On demande <b>Comment vas-tu ?</b> pour savoir si quelqu'un se porte bien."},{"id":"g1fr-eo-024","q":"La maîtresse demande : <i>\"Tu aimes l'école ?\"</i> Tu réponds ...","opts":["Mon chien est beau.","Il fait chaud.","Je suis grand.","Oui, j'aime l'école !"],"a":"Oui, j'aime l'école !","hint":"La question demande si tu aimes l'école. Réponds avec \"Oui\" ou \"Non\". (Answer with yes or no.)","exp":"Pour répondre à cette question, on dit <b>\"Oui, j'aime l'école !\"</b> ou \"Non, je n'aime pas l'école.\" Mais j'espère que tu aimes l'école ! Excellent !"}],"g1fr-lecture":[{"id":"g1fr-lec-056","q":"Quel mot désigne quelque chose qu'on mange ?","opts":["vêtement","aliment","outil","meuble"],"a":"aliment","hint":"On mange des aliments pour avoir de l'énergie.","exp":"Un <b>aliment</b> est quelque chose qu'on mange : une pomme, du riz, du pain."},{"id":"g1fr-lec-020","q":"La lettre <b>\"B\"</b> fait quel son dans \"ballon\" ?","opts":["/d/ comme dent","/b/ comme bébé","/p/ comme pain","/v/ comme vent"],"a":"/b/ comme bébé","hint":"Le son /b/ est fort. (The /b/ sound is strong.)","exp":"La lettre <b>B</b> fait le son <b>/b/</b> — comme dans <i>ballon, bébé, bateau, bras</i>. Très bien !"},{"id":"g1fr-lec-035","q":"Quel mot veut dire <b>\"bird\"</b> en français ?","opts":["lapin","poisson","chat","oiseau"],"a":"oiseau","hint":"Cet animal a des ailes et peut voler. (This animal has wings and can fly.)","exp":"<b>Oiseau</b> veut dire bird. Le poisson = fish, le lapin = rabbit, le chat = cat. Excellent !"},{"id":"g1fr-lec-008","q":"Combien de syllabes a le mot <b>\"o-range\"</b> ?","opts":["1","4","3","2"],"a":"2","hint":"Tape dans tes mains : o — range. (Clap: o — range.)","exp":"\"O-range\" a <b>2 syllabes</b> : <b>o</b> + <b>range</b>. L'orange est un fruit et aussi une couleur ! Très bien !"},{"id":"g1fr-lec-018","q":"La lettre <b>\"A\"</b> est ...","opts":["un mot","une voyelle","un chiffre","une consonne"],"a":"une voyelle","hint":"Les voyelles en français sont : a, e, i, o, u. (The vowels in French are: a, e, i, o, u.)","exp":"La lettre <b>A</b> est <b>une voyelle</b>. Les 5 voyelles sont : <b>a, e, i, o, u</b>. Toutes les autres lettres sont des consonnes. Super !"}]},"grade1-health":{"g1he-hygiene":[{"id":"g1he-hyg-051","q":"Should we wash our hands before eating our school lunch?","opts":["Yes — always","Only if a teacher watches","No — our hands look clean","Only if we ate with our hands before"],"a":"Yes — always","hint":"","exp":"We should <b>always wash hands before eating</b> to remove germs we cannot see."},{"id":"g1he-hyg-019","q":"When we wash our hands, what do we do straight after rubbing them with soap?","opts":["Eat straight away","Rinse our hands","Add more soap","Wipe on our clothes"],"a":"Rinse our hands","hint":"We need to wash the soap away.","exp":"After rubbing in the soap we <b>rinse our hands</b> with clean water, to wash all the soap and germs away."},{"id":"g1he-hyg-020","q":"What is the LAST step when washing our hands?","opts":["Dry our hands","Wet our hands","Apply soap","Rub our hands"],"a":"Dry our hands","hint":"Think about what we do after rinsing.","exp":"The last step is to <b>dry our hands</b> with a clean towel or paper towel."},{"id":"g1he-hyg-003","q":"Why should we wear clean clothes every day?","opts":["To run much faster","To sleep for longer","To eat better food","To stay healthy"],"a":"To stay healthy","hint":"Think about dirt and germs on clothes.","exp":"Wearing <b>clean clothes</b> keeps us looking nice and prevents germs from staying on our skin."},{"id":"g1he-hyg-055","q":"Why is it important NOT to share towels for drying hands?","opts":["Shared towels get wet","Germs pass on the towel","Towels wear out faster","There is no reason"],"a":"Germs pass on the towel","hint":"","exp":"A shared towel can transfer <b>germs from one person to the next</b>. Use your own towel or paper towels."}],"g1he-nutrition":[{"id":"g1he-nut-001","q":"Which of these is a fruit?","opts":["Rice","Fish","Mango","Bread"],"a":"Mango","hint":"Fruits grow on trees or plants and are often sweet.","exp":"<b>Mango</b> is a fruit. Fruits grow on trees and plants and are full of vitamins."},{"id":"g1he-nut-003","q":"Which food gives us energy to run and play?","opts":["Water only","Rice and bread","Sweets only","A little oil"],"a":"Rice and bread","hint":"Starchy foods give us energy.","exp":"<b>Rice and bread</b> are starchy foods that give us energy to play, run and learn."},{"id":"g1he-nut-058","q":"What is a healthy snack that does NOT have a lot of sugar?","opts":["Fizzy drink","Chocolate","Sweets","Carrot sticks"],"a":"Carrot sticks","hint":"","exp":"<b>Carrot sticks</b> are a healthy snack with vitamins and fibre but almost no added sugar."},{"id":"g1he-nut-027","q":"Why do we eat three meals a day?","opts":["To help us sleep well","To give our body energy","Because we feel bored","Because the teacher says"],"a":"To give our body energy","hint":"Think about what food does for our body.","exp":"We eat three meals a day to give our body a steady supply of <b>energy and nutrients</b> throughout the day."},{"id":"g1he-nut-030","q":"Food should be cooked or kept clean so that it is:","opts":["Very cold only","Safe to eat","Very hot only","Only very tasty"],"a":"Safe to eat","hint":"Think about why we cook food.","exp":"Food should be <b>safe to eat and free from germs</b>. Cooking and proper storage kill harmful bacteria."}],"g1he-safety":[{"id":"g1he-saf-003","q":"What should you do if you see a wet floor at school?","opts":["Tell a teacher","Walk through it","Run across it fast","Jump over it"],"a":"Tell a teacher","hint":"Wet floors are slippery.","exp":"Wet floors are slippery and dangerous. You should <b>walk around carefully</b> and <b>tell a teacher</b> so it can be cleaned."},{"id":"g1he-saf-044","q":"Where should medicine be stored in a home with young children?","opts":["On the kitchen table","In a child’s bedroom","On the floor by the door","In a locked cupboard"],"a":"In a locked cupboard","hint":"","exp":"Medicine should be stored in a <b>locked cupboard, out of reach</b>. Children might accidentally take too much, which can be very dangerous."},{"id":"g1he-saf-010","q":"Why is it important to hold the handrail when going up or down stairs?","opts":["Because it is pretty","To prevent falling","To show off","To go faster"],"a":"To prevent falling","hint":"Handrails are there to keep us safe.","exp":"Holding the <b>handrail</b> on stairs prevents us from falling if we slip. Always use it."},{"id":"g1he-saf-022","q":"What should you do if there is a fire at home?","opts":["Stay and watch the fire","Hide under the bed","Put the fire out yourself","Get out and call an adult"],"a":"Get out and call an adult","hint":"Safety first — get away from fire.","exp":"If there is a fire, <b>get out of the house immediately</b> and call for an adult or emergency services. Never hide inside."},{"id":"g1he-saf-029","q":"You see a bottle of liquid with a skull and crossbones symbol. What does this mean?","opts":["It is a fun drink","It is for children","It is clean water","It is poisonous"],"a":"It is poisonous","hint":"The skull and crossbones is a universal warning symbol.","exp":"A <b>skull and crossbones</b> means the substance is <b>poisonous</b>. Never touch or open it — tell an adult immediately."}]},"grade1-maths":{"g1mth-numbers":[{"id":"g1mth-num-009","q":"What number is between 4 and 6?","opts":["7","4","3","5"],"a":"5","hint":"Count: 4, ___, 6.","exp":"<b>5</b> is between 4 and 6."},{"id":"g1mth-num-039","q":"How do we write 10 in words?","opts":["one","twenty","two","ten"],"a":"ten","hint":"10 is a special number — it starts the \"teens\".","exp":"10 is written as <b>ten</b>."},{"id":"g1mth-num-021","q":"Count the apples: 🍎🍎🍎🍎🍎🍎🍎🍎🍎🍎🍎. How many?","opts":["10","9","12","11"],"a":"11","hint":"Count each apple carefully.","exp":"There are <b>11</b> apples."},{"id":"g1mth-num-070","q":"Mia picks 6 flowers. She wants to put them in 2 vases with the same number in each. How many go in each vase?","opts":["6","3","4","2"],"a":"3","hint":"6 is even. Split 6 into two equal groups.","exp":"6 ÷ 2 = <b>3</b>. Three flowers go in each vase."},{"id":"g1mth-num-023","q":"A caterpillar has 20 legs. If 3 legs are hidden, how many can you see?","opts":["13","17","18","16"],"a":"17","hint":"Start at 20 and count back 3.","exp":"<b>17</b> legs can be seen. 20 − 3 = 17."}],"g1mth-addition":[{"id":"g1mth-add-052","q":"Which sign goes in the box: 3 □ 5 = 8?","opts":["×","÷","−","+"],"a":"+","hint":"3 and 5 are being joined together to make 8.","exp":"3 <b>+</b> 5 = 8. We add to join numbers."},{"id":"g1mth-add-027","q":"Tom has 9 lychees. He picks 6 more. How many does he have?","opts":["14","13","16","15"],"a":"15","hint":"9 + 6 = ?","exp":"9 + 6 = <b>15</b>. Tom has 15 lychees."},{"id":"g1mth-add-063","q":"4 + □ = 13. What is □?","opts":["7","8","9","10"],"a":"9","hint":"Count on from 4 to reach 13.","exp":"4 + <b>9</b> = 13."},{"id":"g1mth-add-067","q":"Mia collects □ shells. After finding 7 more she has 16. How many did she start with?","opts":["10","9","7","8"],"a":"9","hint":"□ + 7 = 16. Count back from 16.","exp":"<b>9</b> + 7 = 16. Mia started with 9 shells."},{"id":"g1mth-add-049","q":"Mia has 5 rupees. She earns 12 more. How much does she have in total?","opts":["17","18","15","16"],"a":"17","hint":"5 + 12 = ?","exp":"5 + 12 = <b>17</b>. Mia has 17 rupees."}],"g1mth-subtraction":[{"id":"g1mth-sub-008","q":"Tom has 10 lychees. He gives 4 to Dev. How many does Tom have left?","opts":["5","6","4","7"],"a":"6","hint":"10 − 4 = ?","exp":"10 − 4 = <b>6</b>. Tom has 6 lychees left."},{"id":"g1mth-sub-005","q":"Rani has 6 mangoes. She eats 2. How many are left?","opts":["5","6","4","3"],"a":"4","hint":"6 − 2 = ?","exp":"6 − 2 = <b>4</b>. Rani has 4 mangoes left."},{"id":"g1mth-sub-075","q":"Which number goes in the box? 20 − □ = 14","opts":["7","6","5","4"],"a":"6","hint":"What do you take from 20 to get 14?","exp":"20 − <b>6</b> = 14."},{"id":"g1mth-sub-014","q":"Mia has 8 rupees. She buys a pencil for 3 rupees. How much does she have left?","opts":["6","3","5","4"],"a":"5","hint":"8 − 3 = ?","exp":"8 − 3 = <b>5</b>. Mia has 5 rupees left."},{"id":"g1mth-sub-018","q":"Dev has 7 stickers. He gives 5 to Rani. How many does Dev have?","opts":["3","1","2","4"],"a":"2","hint":"7 − 5 = ?","exp":"7 − 5 = <b>2</b>. Dev has 2 stickers left."}]}}};
